type CentiPoint = { x: number; y: number };
type CentiColor = string | number | MacroFlushSvgPaint;
type CentiEasing = (progress: number) => number;

interface MacroFlushDisplayObject {
  readonly id: string;
  readonly assetId: string;
  x: number;
  y: number;
  scale: number;
  rotation: number;
  opacity: number;
  visible: boolean;
  volume?: number;
  clip?: Record<string, unknown>;
  zIndex?: number;
  width?: number;
  height?: number;
  anchorPoint?: [number, number];
  blendMode?: string;
  parent?: MacroFlushDisplayObject | string;
  mask?: MacroFlushDisplayObject | string;
  instanceOf?: MacroFlushDisplayObject | string;
  remove(): void;
}

interface MacroFlushSvgPoint {
  x: number;
  y: number;
}

interface MacroFlushSvgPaintStop {
  offset: number;
  css: string;
  r: number;
  g: number;
  b: number;
  a: number;
}

interface MacroFlushSvgPaint {
  type: "color" | "none" | "gradient" | "pattern";
  /** Computed CSS paint value. Pass flat colors directly to col(). */
  css: string;
  r: number;
  g: number;
  b: number;
  /** Alpha in Centi's 0-255 convention, including fill/stroke opacity for flat colors. */
  a: number;
  /** RGB packed as 0xRRGGBB for hcol(). */
  int: number;
  hex: string;
  stops?: MacroFlushSvgPaintStop[];
}

interface MacroFlushSvgStyle {
  fill: MacroFlushSvgPaint;
  stroke: MacroFlushSvgPaint;
  strokeWidth: number;
  fillRule: string;
  opacity: number;
}

interface MacroFlushSvgSubpath {
  closed: boolean;
  points: MacroFlushSvgPoint[];
}

interface MacroFlushSvgShape {
  id: string | null;
  tag: "path" | "rect" | "circle" | "ellipse" | "line" | "polyline" | "polygon";
  groupIds: string[];
  /** Length after the shape's SVG transforms have been applied. */
  length: number;
  /** Original geometry length before SVG transforms. */
  localLength: number;
  bbox: { x: number; y: number; width: number; height: number };
  closed: boolean;
  style: MacroFlushSvgStyle;
  subpathCount: number;
  /** Returns one point array for each SVG subpath in SVG viewBox user units. */
  points(count?: number): MacroFlushSvgPoint[][];
  subpaths(count?: number): MacroFlushSvgSubpath[];
}

interface MacroFlushSvgAsset {
  viewBox: { x: number; y: number; width: number; height: number };
  intrinsic: { width: number; height: number } | null;
  shapes: MacroFlushSvgShape[];
}

declare function add(name: string, options?: Partial<Omit<MacroFlushDisplayObject, "id" | "assetId" | "remove">>): MacroFlushDisplayObject;
declare function go(name: string): void;
declare function sendOsc(address: string, ...values: (number | string | boolean)[]): void;
/** Look up a project Data asset (added via File > Load JSON) by name and return its parsed value. */
declare function data(name: string): any;
/** Recorded data, not shader feedback. sample uses Clip-local time/mapping; at/events use recording-local seconds.
 * Standard DOM/p5 input requires a saved Pointer assignment; reading this API does not enable it.
 * Seek/still frames sample with zero handlers. Stateful handlers retain JS history; isolated Feedback is unsupported (P4).
 */
declare function feedback(name: string, mapping?: { offset?: number; rate?: number; loop?: boolean }): MacroFlushFeedback;
type MacroFlushFeedbackSpace = "composition" | "normalized" | "clip";
type MacroFlushFeedbackOptions = { space?: MacroFlushFeedbackSpace };
type MacroFlushFeedbackPointer = { readonly kind: "pointer"; readonly x: number; readonly y: number; readonly buttons: number; readonly inside: boolean };
type MacroFlushFeedbackSample = MacroFlushFeedbackPointer
  | { readonly kind: "number"; readonly value: number | readonly number[] }
  | { readonly kind: "osc"; readonly address: string; readonly args: readonly (number | string | boolean)[] } | null;
type MacroFlushFeedbackEvent = { readonly channelId: string; readonly time: number; readonly seq: number } & (
  | (MacroFlushFeedbackPointer & { readonly event: "move" | "down" | "up" | "enter" | "leave" | "cancel" | "click" | "double-click" | "wheel";
      readonly button?: number; readonly deltaX?: number; readonly deltaY?: number })
  | { readonly kind: "osc"; readonly address: string; readonly args: readonly (number | string | boolean)[] });
interface MacroFlushFeedback {
  readonly duration: number;
  readonly channels: readonly { readonly id: string; readonly kind: string; readonly supported: boolean; readonly records: number }[];
  /** Current Clip-local time mapped through offset/rate/loop. clip space fits logical canvas dimensions, not placement hit testing. */
  sample(channelId: string, options?: MacroFlushFeedbackOptions): MacroFlushFeedbackSample;
  /** Explicit Feedback-local seconds; mapping is not applied. Endpoint hold outside the recording. */
  at(channelId: string, seconds: number, options?: MacroFlushFeedbackOptions): MacroFlushFeedbackSample;
  /** Feedback-local (from,to] seconds; max 4096 events. Wheel deltas scale with space. */
  events(channelId: string, from: number, to: number, options?: MacroFlushFeedbackOptions): readonly MacroFlushFeedbackEvent[];
}
/** Evaluate a Project Script once per Clip iframe and return its exports. Names or stable asset IDs are accepted. */
declare function useScript<T = Record<string, unknown>>(nameOrId: string): T;
/** Returns 0 when no matching audio Clip is active at the composition playhead. */
declare function audioBand(name: string, band: "low" | "mid" | "high", clipId?: string): number;
/** Returns a zero-filled spectrum when no matching audio Clip is active. */
declare function audioSpectrum(name: string, clipId?: string): Float32Array;
/** Asset-local waveform data, available even when the audio Clip is inactive. */
declare function audioPeaks(name: string): { duration: number; minimum: Float32Array; maximum: Float32Array } | null;
/** Asset-local frame-major spectrum data. */
declare function audioSpectrogram(name: string): { duration: number; fps: number; bins: number; buckets: number; data: Float32Array } | null;
/** A stem's combined energy, or one frequency band when specified. */
declare function audioStem(name: string, stem: "vocals" | "drums" | "bass" | "other", band?: "low" | "mid" | "high", clipId?: string): number;
declare function audioStemPeaks(name: string, stem: "vocals" | "drums" | "bass" | "other"): { duration: number; minimum: Float32Array; maximum: Float32Array } | null;
declare function audioStemSpectrogram(name: string, stem: "vocals" | "drums" | "bass" | "other"): { duration: number; fps: number; bins: number; buckets: number; data: Float32Array } | null;
/** Read an embedded SVG Image asset as vector geometry in SVG viewBox user units. */
declare function assetSvg(name: string): MacroFlushSvgAsset;
/** Read a preloaded Project Image asset. Use a string literal name; for computed names use assetImageLoad(). */
declare function assetImage(name: string): HTMLImageElement;
/** Decode a Project Image asset with a computed name. Await in async setup() or another async callback. */
declare function assetImageLoad(name: string): Promise<HTMLImageElement>;
/** Read a preloaded Project Image as a shared THREE.Texture. Requires Three.js; use a string literal name and do not dispose the texture. */
declare function assetTexture(name: string, options?: { colorSpace?: "srgb" | "linear" }): any;
/** Load a shared THREE.Texture with a computed asset name. Requires Three.js; do not dispose the texture. */
declare function assetTextureLoad(name: string, options?: { colorSpace?: "srgb" | "linear" }): Promise<any>;

interface MacroFlushFrame {
  /** Seconds since this clip's In point. */
  time: number;
  /** Frames since this clip's In point. */
  frame: number;
  /** Progress through this clip's visible duration, from 0 to 1. */
  progress: number;
  /** Seconds at the composition playhead. */
  compTime: number;
  /** Frame at the composition playhead. */
  compFrame: number;
  /** Seconds since the MacroFlush editor or player started. */
  runTime: number;
  /** Frames elapsed since app start, at the composition's fps. */
  runFrame: number;
  /** 1-indexed bar at the composition playhead, assuming a 4/4 time signature. */
  bar: number;
  /** 1-indexed beat within the current bar (1-4), assuming a 4/4 time signature. */
  beat: number;
  /** Name of the authored cue currently active at this composition frame, if any. */
  cueName: string | null;
}

interface MacroFlushParamDefinition {
  type?: "number" | "string" | "boolean" | "color" | "vec2" | "vec3" | "select";
  default?: unknown;
  value?: unknown;
  label?: string;
  writable?: boolean;
  min?: number;
  max?: number;
  step?: number;
  options?: string[];
  interpolable?: boolean;
}

interface MacroFlushClip {
  [key: string]: any;
  meta: Record<string, Record<string, unknown>>;
  /** Custom declarations are writable by default; use writable: false to opt out. Built-in transform keys remain host-owned but assignment requests an update to this Clip's host transform. */
  defineParams(definitions: Record<string, MacroFlushParamDefinition>): void;
  /** Read another Clip's evaluated parameter in setup()/onFrame(). Use a Timeline placement ID, not an asset name; missing IDs or keys throw. */
  getParam(placementId: string, key: string): any;
  /** Write a transient override during onFrame(). ID/key must be string literals; only writable custom HTML/Shader parameters are supported, never built-in transforms. */
  setParam(placementId: string, key: string, value: number | boolean | string | number[]): void;
  /** Enable Canvas2D drawing helpers; global installation is enabled unless global: false. Cannot be combined with centi3d. */
  use(name: "centi", options?: { global?: boolean }): CentiApi;
  /** Enable the Three.js scene helper. THREE/T globals are installed unless global: false. Cannot be combined with centi. */
  use(name: "centi3d", options?: { global?: boolean }): Centi3dApi;
  /** Select host-driven p5 global mode; requires the p5 capability and an approved global Library. In this mode clip is callable and cannot be combined with centi/centi3d. */
  use(name: "p5"): void;
  markDirty(): void;
}

interface CentiVec2 extends CentiPoint {
  set(x: number, y: number): this;
  clone(): CentiVec2;
  equals(point: CentiPoint | [number, number]): boolean;
  normalized(): CentiVec2;
  normalize(): void;
  dist(): number;
  dist(point: CentiPoint): number;
  dist(x: number, y: number): number;
  distance(): number;
  distance(point: CentiPoint): number;
  distance(x: number, y: number): number;
  dot(point: CentiPoint): number;
  cross(point: CentiPoint): number;
  rotation(point?: CentiVec2): number;
  setRotation(radians: number): void;
  len(): number;
  setLen(length: number): void;
  rotate(radians: number, center?: CentiPoint): CentiVec2;
  add(point: CentiPoint): CentiVec2;
  subtract(point: CentiPoint): CentiVec2;
  multiply(point: CentiPoint): CentiVec2;
  divide(point: CentiPoint): CentiVec2;
  modulo(point: CentiPoint): CentiVec2;
  negate(): CentiVec2;
  isZero(): boolean;
}

interface CentiRectangle {
  x: number; y: number; w: number; h: number;
  width: number; height: number; right: number; bottom: number; r: number; b: number;
}

interface CentiMatrix {
  set(a: number, c: number, b: number, d: number, tx: number, ty: number): this;
  clone(): CentiMatrix;
  equals(matrix: CentiMatrix): boolean;
  reset(): this;
  apply(): boolean;
  translate(x: number, y: number): this;
  scale(x: number, y: number, cx?: number, cy?: number): this;
  rotate(degrees: number, x?: number, y?: number): this;
  shear(x: number, y: number, cx?: number, cy?: number): this;
  skew(x: number, y: number, cx?: number, cy?: number): this;
  concatenate(matrix: CentiMatrix): this;
  preConcatenate(matrix: CentiMatrix): this;
  chain(matrix: CentiMatrix): CentiMatrix;
  isIdentity(): boolean;
  orNullIfIdentity(): CentiMatrix | null;
  isInvertible(): boolean;
  isSingular(): boolean;
  transform(point: CentiPoint | [number, number] | number, y?: number): CentiVec2;
  transform(source: number[], destination: number[], count: number): number[];
  inverseTransform(point: CentiPoint | [number, number] | number, y?: number): CentiVec2 | null;
  decompose(): { scaling: CentiVec2; rotation: number; shearing: number } | null;
  getValues(): [number, number, number, number, number, number];
  getTranslation(): CentiVec2;
  getScaling(): CentiVec2 | undefined;
  getRotation(): number | undefined;
  inverted(): CentiMatrix | null;
  shiftless(): CentiMatrix;
  applyToContext(context: CanvasRenderingContext2D): void;
}

interface TimelineTween<T extends Record<string, unknown> = Record<string, unknown>> {
  to(target: Partial<T>, duration?: number): this;
  easing(callback: CentiEasing): this;
  delay(duration: number): this;
  repeat(count?: number): this;
  yoyo(enabled?: boolean): this;
  onUpdate(callback: (value: T, progress: number) => void): this;
  onComplete(callback: (value: T) => void): this;
  start(time?: number): this;
  stop(): this;
  isPlaying(): boolean;
  update(time: number): boolean;
}

interface CentiEaseFamily {
  In: CentiEasing;
  Out: CentiEasing;
  InOut: CentiEasing;
}

interface CentiEase {
  Linear: { None: CentiEasing };
  Quadratic: CentiEaseFamily;
  Cubic: CentiEaseFamily;
  Quartic: CentiEaseFamily;
  Quintic: CentiEaseFamily;
  Sinusoidal: CentiEaseFamily;
  Exponential: CentiEaseFamily;
  Circular: CentiEaseFamily;
  Back: CentiEaseFamily;
  Elastic: CentiEaseFamily;
  Bounce: CentiEaseFamily;
  Smoothstep: { InOut: CentiEasing };
  Smootherstep: { InOut: CentiEasing };
}

interface CentiApi { [key: string]: any; }

interface Centi3dApi {
  scene: any;
  camera: any;
  renderer: any;
  T: any;
  /** Construct a Three.js object; PointLight/SpotLight intensities follow Centi's convention. */
  new3d(constructor: any, args?: ArrayLike<any> | Iterable<any>): any;
  /** Return a managed 3D object by its Timeline placement ID, or null if it does not exist. */
  getObject(placementId: string): any;
}

/** MacroFlush parameter proxy. Properties are available after Create Parameters. */
declare const clip: MacroFlushClip;
/** Composition-scoped parameter proxy. Values are shared by every clip in this composition. */
declare const comp: Record<string, any>;
declare const THREE: any;
declare const T: any;
/** Register a callback driven exclusively by MacroFlush's master timeline. */
declare function onFrame(callback: (frame: MacroFlushFrame) => void): void;
/** Register a callback invoked once before the first timeline tick. */
declare function setup(callback: () => void): void;
/** Register a callback invoked every time this clip becomes active (its playhead enters the clip's in/out range), including re-entries. */
declare function onEnter(callback: (frame: MacroFlushFrame) => void): void;
/** Register a callback invoked once per musical beat (4/4 time signature, driven by the composition's BPM) while this clip is active. */
declare function onBeat(callback: (frame: MacroFlushFrame) => void): void;
/** Register a callback invoked when this clip enters an authored composition cue. */
declare function onCue(callback: (frame: MacroFlushFrame) => void): void;
/** Register a callback for a named event broadcast by player.emit(). */
declare function onEvent(name: string, callback: (payload: any) => void): void;

/** Set canvas size in pixels. Editing direct global size(720, 360) inside a top-level inline setup callback synchronizes Inspector size; dynamic values belong in onFrame() before drawing. Host params/keyframes still apply after setup; p5 and instance targets are excluded from declaration sync. */
declare function size(width: number, height: number): void;
/** Alias of size(); direct setup literals synchronize Inspector on source edits only, not on project open. Other existing placements/defaults/tracks are preserved. Use onFrame() for dynamic values. */
declare function sz(width: number, height: number): void;
declare function getContext(): CanvasRenderingContext2D;
declare function clear(): void;
/** Clear using the current background, or set it with packed 0xRRGGBB, CSS color, or RGB(A) channels. */
