declare function bg(...values: number[] | [string]): void;
declare function col(color: string | MacroFlushSvgPaint): void;
declare function col(...values: number[]): void;
declare function hcol(hex: number, alphaOverride?: number): void;
/** Convert exactly #rrggbb to packed 0xRRGGBB. Enabled by clip.use("centi"); invalid strings throw. */
declare function hexToInt(hex: string): number;
/** Convert an integer in 0x000000..0xffffff to lowercase #rrggbb. Enabled by clip.use("centi"); invalid values throw. */
declare function intToHex(value: number): string;
